from ta_tshark_hex_parser.msg_type_to_msg_name_from_hex import get_str_value_of_bits_in_range,\
    convert_bin_to_dec, get_n_bytes_and_convert_to_bitstring
from ta_messaging.ap_procedure_types import AP_PROCEDURE_TYPES

AP_PROTOCOL_IDS = {
    18: 'S1AP',
    27: 'X2AP',
    44: 'M3AP',
    60: 'NGAP',
    61: 'XnAP',
    62: 'F1AP',
    64: 'E1AP',
    3840: 'DYNAMIC_E1AP_F1AP'
}


def get_message_type_from_hex_and_protocol(hex, dec_protocol_id, dynamic_protocol_name=None):
    """
    Derives message type from hex, based on specified protocol
    """
    assert dynamic_protocol_name is None or dynamic_protocol_name in list(AP_PROTOCOL_IDS.values()),\
        'Dynamic protocol name: {} must be one of already implemented protocols: {}'\
        .format(dynamic_protocol_name, list(AP_PROTOCOL_IDS.values()))
    dec_protocol_id = int(dec_protocol_id)
    assert int(dec_protocol_id) in list(AP_PROTOCOL_IDS.keys()), 'Protocol ID: {} not supported, allowed: {}'\
        .format(dec_protocol_id, AP_PROTOCOL_IDS)
    assert (dynamic_protocol_name is not None and 'DYNAMIC' in AP_PROTOCOL_IDS[dec_protocol_id]) or \
           (dynamic_protocol_name is None and 'DYNAMIC' not in AP_PROTOCOL_IDS[dec_protocol_id]), \
           'Received protocol id: {} is dynamic and does not have dynamic protocol name specified: {} ' \
           'OR received protocol: {} is non-dynamic while protocol name is specified: {}'\
           .format(dec_protocol_id, dynamic_protocol_name, dec_protocol_id, dynamic_protocol_name)
    if not dynamic_protocol_name:
        protocol_name = str(AP_PROTOCOL_IDS[dec_protocol_id]).lower()
    else:
        protocol_name = str(dynamic_protocol_name).lower()
    available_protocols = list(AP_PROCEDURE_TYPES.keys())
    assert protocol_name in available_protocols, 'Protocol not recognized {}:{}, allowed protocols: {}'\
        .format(dec_protocol_id, protocol_name, available_protocols)
    dec_procedure_type = get_ap_pdu_choice_index(hex, protocol_name)  # e.g. 0 - initiating, 1 -success response, 2 - unsucess response
    dec_msg_type_value = get_message_type_value(hex)  # e.g. for initiating mesagge msg type=0 means HandoverRequired

    if dec_procedure_type not in AP_PROCEDURE_TYPES[protocol_name]:
        raise Exception('Unsupported procedure type: {} for protocol: {}'.format(dec_procedure_type, protocol_name))
    if dec_msg_type_value not in AP_PROCEDURE_TYPES[protocol_name][dec_procedure_type]:
        raise Exception('Unsupported message type: {} for protocol: {} and procedure type: {}'
                        .format(dec_msg_type_value, protocol_name, dec_procedure_type))
    msg_name = AP_PROCEDURE_TYPES[protocol_name][dec_procedure_type][dec_msg_type_value]
    return msg_name, protocol_name


def get_ap_pdu_choice_index(hex, protocol=None):
    """
    Generic for all protocols, receives decimal value of procedure code: 0 - initiating, 1 -success response, 2 - unsucess response
    """
    bits_range_per_proto = {'default': [2, 3],
                            'specific':
                                {'f1ap': [1, 2]}
                            }
    eight_bits = get_n_bytes_and_convert_to_bitstring(hex, 1)
    # robot_logger.console(protocol)
    # robot_logger.console(eight_bits)
    if protocol in list(bits_range_per_proto['specific'].keys()):
        [start_bit, stop_bit] = bits_range_per_proto['specific'][protocol]
    else:
        [start_bit, stop_bit] = bits_range_per_proto['default']
    ap_proc_type = get_str_value_of_bits_in_range(start_bit, stop_bit, eight_bits)
    dec_proc_type = convert_bin_to_dec(ap_proc_type)
    # robot_logger.console(dec_proc_type)
    return dec_proc_type


def get_message_type_value(hex, protocol=None):
    """
    Generic for all protocols, receives choice value - decimal - from hex maessgae
    """
    sixteen_bits = get_n_bytes_and_convert_to_bitstring(hex, 4)
    # robot_logger.console(sixteen_bits)
    message_type = get_str_value_of_bits_in_range(9, 16, sixteen_bits)
    # robot_logger.console(message_type)
    dec_msg_type = convert_bin_to_dec(message_type)
    return dec_msg_type
